MultiLanguageItemData['mx'][84122] = {name = "Receta: frasco de alquimista", additional_info = "Requiere Alquimia (550)\n[q2]Uso: Te enseña a mezclar un frasco de alquimista.\n\n\n[q3]Frasco de alquimista\nSe liga al recogerlo\nRequiere Alquimia (300)\n[q2]Uso: Aumenta tu agilidad, fuerza o intelecto 320 p. durante 2 h. Siempre se elige la estadística más elevada.\n\n Cuenta como elixir guardián y de batalla. El efecto persiste más allá de la muerte.\n[q]\"Se puede usar en las arenas. Este potente frasco no se consume al usarlo, pero no le afecta la ciencia de la mezcla.\"\nRequiere Vial de cristal , Setelo (7), Salviargenta de montaña (7), Champiñón fantasma (7)"}
MultiLanguageItemData['mx'][84123] = {name = "Receta: frasco de hojas otoñales", additional_info = "Requiere Alquimia (550)\n[q2]Uso: Te enseña a mezclar un frasco de hojas otoñales.\nAl elaborar este frasco, tienes una probabilidad de aprender recetas adicionales.\n\n La cantidad de recetas que puedes aprender depende de tu habilidad en Alquimia.\n\n\nFrasco de hojas otoñales\nNecesitas ser de nivel 85\n[q2]Uso: Aumenta el espíritu 1000 p. durante 1 h. Cuenta como elixir de batalla y guardián. El efecto persiste más allá de la muerte. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Vial de cristal , Hoja de té verde (4), Loto dorado"}
MultiLanguageItemData['mx'][84124] = {name = "Receta: poción de sanación maestra", additional_info = "Requiere Alquimia (500)\n[q2]Uso: Te enseña a mezclar una poción de sanación maestra.\nAl elaborar esta poción, tienes una probabilidad de aprender recetas adicionales.\n\n La cantidad de recetas que puedes aprender depende de tu habilidad en Alquimia.\n\n\nPoción de sanación maestra\nNecesitas ser de nivel 85\n[q2]Uso: Restaura 120000 p. de salud. (1 Min Reutilización)\nPrecio de venta:\nRequiere Vial de cristal , Hoja de té verde"}
MultiLanguageItemData['mx'][84125] = {name = "Receta: transmutar resplandor solar", additional_info = "Requiere Alquimia (575)\n[q2]Uso: Te enseña a transmutar un resplandor solar.\nAl realizar esta transmutación, tienes una probabilidad de aprender recetas adicionales.\n\n La cantidad de recetas que puedes aprender depende de tu habilidad en Alquimia.\n\n\n[q3]Resplandor solar\nPrecio de venta: \nRequiere Piedrasol , Loto dorado"}
