MultiLanguageItemData['mx'][86568] = {name = "[q3]Brújula de latón de Don Mamporro", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Libera los recuerdos de un contramaestre olvidado. (Probabilidad de que accione: 5%, 3m de reutilización) (2 H Reutilización)"}
MultiLanguageItemData['mx'][86569] = {name = "[q3]Cristal de locura", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 85\n[q2]Uso: Aumenta todas las estadísticas 500 p. durante 1 h. Cuenta como elixir de batalla y guardián. (15 Min Reutilización)\n[q]\"Casi parece que te devuelve la mirada.\""}
MultiLanguageItemData['mx'][86570] = {name = "[q3]Cajón de cachorros secuestrados", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 85\n[q2]Uso: Libera los cachorros secuestrados para que luchen por ti durante 10 min. (1 Hora Reutilización)\n[q]\"... ¡y comen cachorros!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86571] = {name = "[q3]Piedra de ligación de Kang", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Le infunde el poder de la piedra, lo que otorga una probabilidad al matar a un oponente de encerrarlo en piedra. (Probabilidad de que accione: 33%, 1m de reutilización) (1 Hora Reutilización)\n[q]\"Los ligadores de piedras mogu utilizan estos catalizadores grabados con runas para transformar la carne en piedra.\""}
MultiLanguageItemData['mx'][86572] = {name = "[q3]Fragmento de terracota", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 85\n[q2]Uso: Invoca un guerrero de terracota para que luche a tu lado durante 10 min. (1 Hora Reutilización)\n[q]\"Imbuido de poderosa magia mogu.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86573] = {name = "[q3]Fragmento de piedra de arco", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Te transformas en una estatua mogu, lo que impide seleccionarte como objetivo durante 5 min. (30 Min Reutilización)\n[q]\"Un fragmento de origen desconocido que rebosa de un poder ancestral.\""}
MultiLanguageItemData['mx'][86574] = {name = "[q3]Elixir de conocimiento antiguo", additional_info = "Se liga a la cuenta\n[q2]Uso: Aumenta la experiencia obtenida un 300% durante 1 h. No funciona con jugadores de nivel superior al 84.\n[q]\"Un ligero susurro sale de la botella.\""}
MultiLanguageItemData['mx'][86575] = {name = "[q3]Cáliz de secretos", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Cedes a tu ira durante 10 s. Mientras está activo, el siguiente golpe de gracia que se realice contra un jugador te transformará en un mogu durante 5.50 s, lo que evitará que realices cualquier acción mientras te recreas. (10 Min Reutilización)\n[q]\"Los rituales para profanar la muerte de un oponente caído son inherentes a la cultura mogu.\""}
MultiLanguageItemData['mx'][86576] = {name = "[q3]Dinastía del acero", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 85\n[q2]Uso: Invoca un torbellino de espadas que lucha por ti durante 10 min. (1 Hora Reutilización)\n[q]\"Las técnicas de esgrima de los mántides son un secreto muy bien guardado.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86577] = {name = "[q3]Vara de formas de ámbar", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Encierra al objetivo en ámbar, lo que impide toda acción durante un máximo de 1 min. Cualquier daño infligido romperá el ámbar. No funciona con jugadores u objetivos de nivel superior al 94. (5 Min Reutilización)\n[q]\"Utilizada por los mántides tejedores de ámbar para hilar estructuras de ámbar endurecido.\""}
MultiLanguageItemData['mx'][86578] = {name = "[q3]Sigilo de guerrero eterno", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Restaura un 15% de salud y maná cada 1 s durante 6 s. Cualquier daño recibido eliminará el frenesí. Solo se puede usar en Pandaria. No funciona con jugadores de nivel superior al 94. (5 Min Reutilización)\n[q]\"Concedido al guardia de élite de Shek'zeer por sus servicios a la Emperatriz.\""}
MultiLanguageItemData['mx'][86579] = {name = "[q3]Tornado embotellado", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n[q2]Uso: Salta por los aires. Solo se puede usar en exteriores. (2 Min Reutilización)\n[q]\"Los mántides aprendieron hace mucho a someter a los vientos de Pandaria a la voluntad de la Emperatriz.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86580] = {name = "[q3]Nenúfar desmesurado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Paladín , Cazador , Pícaro , Sacerdote , Caballero de la muerte , Chamán , Mago , Brujo , Monje\n[q2]Uso: Otorga una facultad del druida en función de la clase y función de combate. Solo se puede usar en Pandaria. (1 Hora Reutilización)\n[q]\"Encierra todo un ecosistema en él.\""}
MultiLanguageItemData['mx'][86581] = {name = "[q3]Caracola Agualejana", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Te permite ver a lo lejos y te otorga la facultad de crear gotas de agua. (10 Min Reutilización)\n[q]\"Inscrita con runas jinyu que permiten al usuario comprender la lengua de las olas.\""}
MultiLanguageItemData['mx'][86582] = {name = "[q3]Joya acuática", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\nNecesitas ser de nivel 85\n[q2]Uso: Aumenta la velocidad de nado un 50% y permite respiración bajo el agua durante 10 min. (1 Hora Reutilización)\n[q]\"Recogida de las fauces de Gokk'lok.\""}
MultiLanguageItemData['mx'][86583] = {name = "[q3]Estandarte de batalla Salyin", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\nNecesitas ser de nivel 85\n[q2]Uso: Te fundes con las sombras durante 1 s e invocas a un explorador de guerra Salyin. El explorador de guerra atraerá la atención de los monstruos cercanos y se irá corriendo. (10 Min Reutilización)\n[q]\"Manchado con la sangre de muchos aventureros desafortunados.\""}
MultiLanguageItemData['mx'][86584] = {name = "[q3]Caparazón endurecido", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Lanza un caparazón duro, lo que desmonta al objetivo. No se puede usar con objetivos de nivel superior al 94. (15 Min Reutilización)\n[q]\"Parece injusto.\""}
