MultiLanguageItemData['mx'][94525] = {name = "[q4]Reliquia robada de Zuldazar", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Stolen Relic of Zuldazar] (1)\nAbalorio\n+1.467 espíritu\nNecesitas ser de nivel 90\n[q2]Equipar: Tus hechizos de ayuda tienen la posibilidad de otorgarte la Bendición de Zuldazar, que se acumula hasta 6 veces. (Aproximadamente 2.89 procs por minuto).\n[q2]Uso: Consume todas las bendiciones de Zuldazar para proteger al objetivo, lo que absorbe 9339 p. de daño por bendición consumida. Dura 15 s. (20 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][94526] = {name = "[q4]Chispa de Zandalar", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Spark of Zandalar] (1)\nAbalorio\n[q2]Aumenta tu índice de celeridad + 1.467 p.\nNecesitas ser de nivel 90\n[q2]Equipar: Tus ataques tienen la posibilidad de otorgarte una chispa de Zandalar. Una vez que hayas acumulado 10 chispas, te transformarás en un guerrero Zandalari y obtendrás 700 p. de fuerza durante 10 s. (Aproximadamente 11.10 procs por minuto).\nPrecio de venta:"}
MultiLanguageItemData['mx'][94527] = {name = "[q4]Vientos crecientes de Ji Kun", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Ji-Kun's Rising Winds] (1)\nAbalorio\n[q2]Aumenta tu índice de pericia + 1.467 p.\nNecesitas ser de nivel 90\n[q2]Equipar: Los ataques cuerpo a cuerpo que reducen tu salud por debajo de un 35% provocan que te sanes 40341 p. al instante. No puede ocurrir más de una vez cada 30 s. (30s de reutilización)\nPrecio de venta:"}
